package toml

import "testing"

func TestDecodeEmptyDocument(t *testing.T) {
	got, err := Decode("")
	if err != nil {
		t.Fatalf("Decode(empty) returned error: %v", err)
	}
	if got == nil {
		t.Fatal("Decode(empty) returned nil document")
	}
	if len(got) != 0 {
		t.Fatalf("Decode(empty) returned %v, want empty document", got)
	}
}

func TestDecodeUnsupportedInputReturnsError(t *testing.T) {
	if _, err := Decode("answer = 42\n"); err == nil {
		t.Fatal("Decode(non-empty) returned nil error")
	}
}
