package main

import (
	"encoding/json"
	"fmt"
	"io"
	"os"

	"github.com/owner/toml-decoder/internal/toml"
)

func main() {
	if len(os.Args) != 1 {
		fmt.Fprintln(os.Stderr, "toml-decoder accepts no arguments")
		os.Exit(2)
	}
	input, err := io.ReadAll(os.Stdin)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	tagged, err := toml.Decode(string(input))
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	if err := json.NewEncoder(os.Stdout).Encode(tagged); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}
// Package toml contains the TOML decoder and its tagged value model.
package toml

import (
	"fmt"
	"strconv"
	"strings"
)

// Value is the JSON representation of a TOML scalar value.
type Value struct {
	Type  string `json:"type"`
	Value string `json:"value"`
}

// Document is the JSON representation of a TOML document.
type Document map[string]any

// Decode parses a TOML document and returns its tagged representation.
func Decode(input string) (Document, error) {
	document := Document{}
	for lineNumber, line := range strings.Split(strings.ReplaceAll(input, "\r\n", "\n"), "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		key, rawValue, ok := strings.Cut(line, "=")
		if !ok {
			return nil, fmt.Errorf("line %d: expected key-value pair", lineNumber+1)
		}
		key = strings.TrimSpace(key)
		rawValue = strings.TrimSpace(strings.SplitN(rawValue, "#", 2)[0])
		if key == "" || rawValue == "" {
			return nil, fmt.Errorf("line %d: invalid key-value pair", lineNumber+1)
		}
		if _, exists := document[key]; exists {
			return nil, fmt.Errorf("line %d: duplicate key %q", lineNumber+1, key)
		}
		value, err := decodeInteger(rawValue)
		if err != nil {
			return nil, fmt.Errorf("line %d: %w", lineNumber+1, err)
		}
		document[key] = value
	}
	return document, nil
}

func decodeInteger(raw string) (Value, error) {
	if strings.ContainsAny(raw, "[]{}") {
		return Value{}, fmt.Errorf("unsupported or malformed value")
	}
	if strings.Contains(raw, ".") || strings.ContainsAny(raw, "eE") {
		return Value{}, fmt.Errorf("unsupported value")
	}
	cleaned := strings.ReplaceAll(raw, "_", "")
	base := 10
	digits := cleaned
	if len(cleaned) > 2 && cleaned[0] == '0' {
		switch cleaned[1] {
		case 'x', 'X':
			base, digits = 16, cleaned[2:]
		case 'o', 'O':
			base, digits = 8, cleaned[2:]
		case 'b', 'B':
			base, digits = 2, cleaned[2:]
		}
	}
	if digits == "" {
		return Value{}, fmt.Errorf("invalid integer")
	}
	if _, err := strconv.ParseInt(digits, base, 64); err != nil {
		return Value{}, fmt.Errorf("invalid integer")
	}
	return Value{Type: "integer", Value: raw}, nil
}
